"""Both READMEs document exactly the tools the server registers - see `rules/docs.md`.

`get_queue_metadata` and `queue_get_local_fields` were documented for months without
ever existing, and the entity tools were half-documented in the other direction.
"""

import re
from pathlib import Path

import pytest

from tests.mcp.server.test_tool_conventions import TOOL_IDS, TOOL_NAMES

ROOT = Path(__file__).parents[3]
README_NAMES = ["README.md", "README_ru.md"]
READMES = {name: (ROOT / name).read_text() for name in README_NAMES}

# A tool name in a listing position: a bullet `- **`name`**:` or a table cell
# `| `name` |`. Prose mentions are not matched - only the places that claim to
# enumerate the tool surface.
LISTED_TOOL_PATTERN = re.compile(
    r"^(?:- \*\*`([a-z][a-z0-9_]*)`\*\*|\| *`([a-z][a-z0-9_]*)` *\|)", re.MULTILINE
)


def listed_tools(readme: str) -> set[str]:
    return {name for match in LISTED_TOOL_PATTERN.finditer(readme) for name in match.groups() if name}


@pytest.mark.parametrize("tool_name", TOOL_IDS)
def test_every_tool_is_documented(tool_name: str) -> None:
    for name, text in READMES.items():
        assert f"`{tool_name}`" in text, f"'{tool_name}' is not documented in {name}"


@pytest.mark.parametrize("readme_name", README_NAMES)
def test_no_tool_listing_names_a_tool_that_does_not_exist(readme_name: str) -> None:
    unknown = listed_tools(READMES[readme_name]) - TOOL_NAMES

    assert not unknown, (
        f"{readme_name} lists tools this server does not register: {sorted(unknown)}"
    )

